/* ---- Orphan strings: missed by the Data.c bulk import because they
 * either live only in SWOS2.s or have non-printable bytes that the
 * regex couldn't match. Transcribed verbatim. */
char _aCoach_1[8]                  = "\001COACH:";
char _aCup1[9]                     = "\004C\000U\000P\0001";
char _aCup2[9]                     = "\004C\000U\000P\0002";
char _aCup_10[9]                   = "\004C\000U\000P\000 ";
char _aLge_0[9]                    = "\004L\000G\000E\000 ";
/* aPlayer_1 is a 2-line MULTILINE menu string. Format is
 * `[lineCount][line1\0][line2\0]...`. The original Amiga at
 * SWOS2.s line 127065 declares it as `dc.b 2, 'PLAYER', 0` —
 * 8 bytes ending with the line-1 NUL — and immediately follows
 * it with `aCoach_2: dc.b "-COACH:", 0` (8 more bytes), so the
 * multiline parser reads the second line by continuing past the
 * declared 8-byte aPlayer_1 into the adjacent aCoach_2 storage.
 *
 * On SDL each label is its own symbol and the linker doesn't
 * preserve that adjacency — the parser walks aPlayer_1 + 8 into
 * unrelated BSS and renders garbage as the second line (the
 * red+blue artefact under "PLAYER" on the play-match menu's
 * PLAYER/COACH button that looked like a sock sprite).
 *
 * Fix: hold both lines inline in aPlayer_1 itself. aCoach_2 is
 * still defined elsewhere as a const string but isn't referenced
 * by code — its only role was to be the byte-string immediately
 * following aPlayer_1 on Amiga BSS. */
char _aPlayer_1[16] = {
    2, 'P','L','A','Y','E','R', 0,
    '-','C','O','A','C','H',':', 0
};
char _aPound[2]                    = "\234";
char _aTot_0[9]                    = "\004T\000O\000T\000 ";

/* SWOS2.s leading-byte format (display flag 1=single, 2=multi-line bullet).
 *
 * The format-2 prompts are followed in SWOS2.s by an unnamed second-line
 * label that is rendered after the prompt's null terminator (the renderer
 * walks past the null when it sees format byte 2). On Amiga the adjacent
 * `dc.b ...,0` declarations guarantee the bytes are contiguous; on SDL
 * each `char[]` is a separate symbol with no adjacency guarantee, so the
 * post-null read picked up either zeros or unrelated data and the second
 * line came out blank ("YOU ARE ABOUT TO LOSE CURRENT" with no
 * "CAREER" / "SEASON" / etc. underneath).
 *
 * Fix: embed the second line inside the same `char[]` buffer with an
 * explicit `\0` separator, mirroring the Amiga layout exactly. */
char _aCareerPrompt[]              = "\002  YOU ARE ABOUT TO LOSE CURRENT  \0             CAREER              ";
char _aCustomTeamsChanged[]        = "\001CUSTOM TEAMS HAVE BEEN CHANGED";
char _aDiyCompetitionPrompt[]      = "\002  YOU ARE ABOUT TO LOSE CURRENT  \0         DIY COMPETITION         ";
char _aEditedTacticsWillBeLost[]   = "\001EDITED TACTICS WILL BE LOST";
char _aInsertBlankDis[]            = "\001INSERT BLANK DISK IN DF0:";
char _aInsertGameSave[]            = "\001INSERT GAME SAVE DISK IN DF0:";
char _aInsertSwosDisk_0[]          = "\001INSERT SWOS DISK 2 IN ANY DRIVE";
char _aPresetCompetitionPrompt[]   = "\002  YOU ARE ABOUT TO LOSE CURRENT  \0       PRESET COMPETITION        ";
char _aSeasonPrompt[]              = "\002  YOU ARE ABOUT TO LOSE CURRENT  \0             SEASON              ";
